            "content": "এটি একদিনে personality বদলানোর exercise নয়। পরের সাত দিনে “নিজের অবস্থান ধরে রাখা” সম্পর্কিত অন্তত একটি conversation বেছে নাও। conversation-এর আগে একটি line লিখবে, conversation-এর পরে আরেকটি line: কী বলতে চেয়েছিলে, আর মানুষ কী শুনল বলে মনে হলো। এই দুই লাইনের দূরত্বই তোমার practice map।"
